import { getTerminalList, terminalRemove } from "@/api/terminal";
export default {
  data: function data() {
    return {
      // 搜索相关
      searchForm: {
        ip: undefined,
        status: undefined,
        current: 1,
        size: 20
      },
      // 表格相关
      dataList: [],
      loading: false,
      tableHeight: undefined,
      total: 0,
      deviceStatusList: [{
        label: '1',
        value: '在线'
      }, {
        label: '0',
        value: '离线'
      }]
    };
  },
  mounted: function mounted() {
    // 设置页面元素高度
    this.setPageContentHeight();
    // 设置表格高度
    this.setTableHeight();
    //加载数据
    this.onLoad();
  },
  methods: {
    // 设置表格高度
    setTableHeight: function setTableHeight() {
      var pageBody = document.getElementsByClassName('page_body');
      this.tableHeight = pageBody[0].offsetHeight - 61 - 47 + 'px';
    },
    handleQuery: function handleQuery() {
      this.searchForm.current = 1;
      this.onLoad();
    },
    handleDeleteOne: function handleDeleteOne(id) {
      //删除按钮
      var ids = id;
      this.handleDeleteConfirm(ids);
    },
    handleDeleteConfirm: function handleDeleteConfirm(ids) {
      var _this = this;
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。", "确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function () {
        return terminalRemove(ids);
      }).then(function () {
        _this.onLoad();
        _this.$message({
          type: "success",
          message: "操作成功!"
        });
      });
    },
    searchReset: function searchReset() {
      //重置按钮
      this.searchForm = {
        ip: undefined,
        status: undefined,
        current: 1,
        size: 20
      };
      this.onLoad();
    },
    onLoad: function onLoad() {
      var _this2 = this;
      //加载数据
      this.loading = true;
      getTerminalList(this.searchForm).then(function (res) {
        var data = res.data;
        _this2.total = data.total;
        _this2.dataList = data.records;
        _this2.loading = false;
      });
    },
    // handleView(row) {
    //   //详情 页面
    //   this.$router.push({
    //     path: '/detailRoute',
    //     query: {
    //       id: row.id,
    //       componentName: 'devRecordDetail',
    //       routerTitle: '设备建档详情'
    //     }
    //   });
    // },
    handleEdit: function handleEdit(row) {
      //编辑 页面
      this.$router.push({
        path: '/detailRoute',
        query: {
          id: row.id,
          componentName: 'devRecordAdd',
          routerTitle: '终端编辑'
        }
      });
    },
    handleAdd: function handleAdd() {
      //新增 页面
      this.$router.push({
        path: '/detailRoute',
        query: {
          componentName: 'devRecordAdd',
          routerTitle: '终端新增'
        }
      });
    }
  }
};
